<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/idempotency.php';require_once __DIR__.'/payouts-v2.php';vendor_payouts_v2();exit;
send_cors_headers();$context=require_vendor(true);$vendorId=$context['vendor']['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';
if($method==='GET'){$balances=$db->prepare('SELECT balance_bucket,COALESCE(SUM(amount),0) amount FROM vendor_ledger_entries WHERE vendor_id=:vendor GROUP BY balance_bucket');$balances->execute(['vendor'=>$vendorId]);$balance=['pending'=>0.0,'eligible'=>0.0,'held'=>0.0,'paid'=>0.0,'reversed'=>0.0];foreach($balances->fetchAll() as $row)$balance[$row['balance_bucket']]=(float)$row['amount'];$requests=$db->prepare('SELECT p.id,p.amount,p.status,p.requested_at,p.payment_reference,p.paid_at,b.beneficiary_name,b.account_last4,b.bank_name FROM payout_requests p JOIN vendor_bank_accounts b ON b.id=p.bank_account_id WHERE p.vendor_id=:vendor ORDER BY p.requested_at DESC');$requests->execute(['vendor'=>$vendorId]);json_response(200,['success'=>true,'balance'=>$balance,'available'=>max(0,$balance['eligible']+$balance['reversed']), 'payouts'=>$requests->fetchAll()]);}
if($method==='POST'){$body=get_json_body();$amount=round((float)($body['amount']??0),2);$bankId=trim((string)($body['bank_account_id']??''));if($amount<100)json_response(422,['success'=>false,'message'=>'Minimum payout request is ₹100.']);$idem=begin_idempotent_request('payout.request',['type'=>'vendor','id'=>$vendorId],$body);$db->beginTransaction();try{$bank=$db->prepare('SELECT * FROM vendor_bank_accounts WHERE id=:id AND vendor_id=:vendor AND verification_status="verified" FOR UPDATE');$bank->execute(['id'=>$bankId,'vendor'=>$vendorId]);if(!$bank->fetch())json_response(422,['success'=>false,'message'=>'Choose a verified bank account.']);$sum=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM vendor_ledger_entries WHERE vendor_id=:vendor AND balance_bucket="eligible" FOR UPDATE');$sum->execute(['vendor'=>$vendorId]);$available=(float)$sum->fetchColumn();$held=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payout_requests WHERE vendor_id=:vendor AND status IN ("requested","maker_approved","processing")');$held->execute(['vendor'=>$vendorId]);$available-=(float)$held->fetchColumn();if($amount>$available)json_response(422,['success'=>false,'message'=>'Payout amount exceeds your available balance.']);$id=uuid_string();$db->prepare('INSERT INTO payout_requests (id,vendor_id,bank_account_id,amount,status,requested_at,updated_at) VALUES (:id,:vendor,:bank,:amount,"requested",UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>$id,'vendor'=>$vendorId,'bank'=>$bankId,'amount'=>$amount]);audit_event('vendor.payout_requested','payout_request',$id,['amount'=>$amount]);$response=['success'=>true,'message'=>'Payout request submitted.','payout_id'=>$id,'status'=>'requested'];finish_idempotent_request((int)$idem['id'],201,$response);$db->commit();json_response(201,$response);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
json_response(405,['success'=>false,'message'=>'Method not allowed.']);
